-- the auth trigger created a default profile; set the real one
insert into public.profiles (id, handle, display_name, avatar_url, bio, level, github_login, locale,
  is_guest, onboarded, reputation, created_at) values
  ('127106c4-6185-57e9-bbd6-4c41c8175c6e'::uuid, 'alexmorgan', 'Alex Morgan', '/avatars/alex.jpg', 'Développeur full-stack. Des idées plein la tête, un terminal toujours ouvert. Je construis des outils utiles et je partage ce que j''apprends.', 'intermediate'::public.level_t, null, 'fr', false, true, 164, now() - interval '30 days'),
  ('c5284648-64cb-5e9e-a325-1b7a4dd8f2d7'::uuid, 'sarahbuilds', 'Sarah Chen', '/avatars/sarah.jpg', 'Frontend developer. Je transforme le café en interfaces. JavaScript, accessibilité et les petits détails qui font une grande différence.', 'senior'::public.level_t, null, 'fr', false, true, 482, now() - interval '33 days'),
  ('b8fa65cc-65e1-50ae-aaa8-81cf1e728821'::uuid, 'yanncodes', 'Yann Kouamé', '/avatars/yann.jpg', 'Indie maker, full-stack. Je construis Pollen en public depuis Abidjan. Des outils simples, un peu de design et beaucoup de curiosité.', 'intermediate'::public.level_t, null, 'fr', false, true, 203, now() - interval '36 days'),
  ('1dce1d27-78fb-5179-a912-bd23c57d4895'::uuid, 'leamartin', 'Léa Martin', '/avatars/lea.jpg', 'Design engineer. À la croisée du design et du code. J''aime les interfaces qui se font oublier et les composants bien pensés.', 'senior'::public.level_t, null, 'fr', false, true, 536, now() - interval '39 days'),
  ('a5019547-4c5d-53d0-9581-5355518d3a38'::uuid, 'aminebuilds', 'Amine Benali', '/avatars/amine.jpg', 'Backend engineer à Casablanca. APIs, architecture et bases de données. Toujours partant pour parler des bons compromis et déboguer à plusieurs.', 'senior'::public.level_t, null, 'fr', false, true, 611, now() - interval '42 days'),
  ('c783bb00-c6b1-58ac-b011-7167213746d5'::uuid, 'idrissadev', 'Idrissa Ouédraogo', '/avatars/idrissa.jpg', 'Développeur Python. De Ouaga au monde, une ligne à la fois. Python, data et open source. J''apprends en construisant.', 'intermediate'::public.level_t, null, 'fr', false, true, 187, now() - interval '45 days'),
  ('60409083-840c-5088-b8b7-9d004e795d26'::uuid, 'juliemakes', 'Julie Moreau', '/avatars/julie.jpg', 'Creative developer à Nantes. Du code créatif, des animations et des projets qui donnent le sourire. Je partage mes expérimentations ici.', 'intermediate'::public.level_t, null, 'fr', false, true, 121, now() - interval '48 days'),
  ('36c44435-65df-51e2-9312-3ba3d6757261'::uuid, 'fatoudiallo', 'Fatou Diallo', null, 'Étudiante en L3 informatique à Dakar. J''apprends React le soir et je pose beaucoup de questions, désolée d''avance.', 'beginner'::public.level_t, null, 'fr', false, true, 18, now() - interval '51 days'),
  ('4130c542-5ee6-51eb-a0da-80bd3cb67520'::uuid, 'mat_tremblay', 'Mathieu Tremblay', null, 'SRE à Montréal. Kubernetes le jour, Go la nuit. Si ça plante en prod un vendredi, on jase.', 'senior'::public.level_t, null, 'fr', false, true, 398, now() - interval '54 days'),
  ('92eb883f-d370-5c4f-ba14-20929fde18f2'::uuid, 'nadiahaddad', 'Nadia Haddad', null, 'Développeuse mobile à Tunis. Flutter, Kotlin, et un backend Spring quand il le faut. Fan des apps qui marchent hors ligne.', 'intermediate'::public.level_t, null, 'fr', false, true, 96, now() - interval '57 days'),
  ('88d23a8a-1440-5cf2-bdb1-fe5096088032'::uuid, 'christelle_ng', 'Christelle Ngono', null, 'En reconversion à Yaoundé, ex-comptable. Python, Django et un peu de data. Chaque bug compris est une petite victoire.', 'beginner'::public.level_t, null, 'fr', false, true, 24, now() - interval '60 days'),
  ('63ce7c64-4bf6-55b1-8c81-39efa16132c2'::uuid, 'thomaslefevre', 'Thomas Lefèvre', null, 'Alternant à Lille, PHP/Symfony en entreprise et Java à l''école. J''essaie de comprendre plutôt que de copier-coller.', 'beginner'::public.level_t, null, 'fr', false, true, 12, now() - interval '63 days')
on conflict (id) do update set handle = excluded.handle, display_name = excluded.display_name,
  avatar_url = excluded.avatar_url, bio = excluded.bio, level = excluded.level,
  github_login = excluded.github_login, is_guest = false, onboarded = true,
  reputation = excluded.reputation, created_at = excluded.created_at;

