  ('6d37f68e-c6c7-594a-bc8e-68731d2cc653'::uuid, 'react', 'React', 'Hooks, rendu, état, performances : on débloque les problèmes React ensemble, du premier composant aux cas tordus.', 'Hooks, rendering, state, performance: we unblock React problems together, from the first component to the hairy cases.', (select id from public.interests where slug = 'react'), null, now() - interval '60 days'),
