  ('496ee400-d798-5c41-97d9-06f86016e094'::uuid, 'data-ia', 'Data & IA', 'pandas, modèles, embeddings et RAG : des questions concrètes et des réponses qui tiennent la route en production.', 'pandas, models, embeddings and RAG: concrete questions and answers that hold up in production.', (select id from public.interests where slug = 'data-ai'), null, now() - interval '62 days'),
