  ('9c3a733f-4385-5337-8c12-487fed0fed37'::uuid, 'devops', 'DevOps', 'Docker, CI/CD, déploiements et incidents. On partage les post-mortems, pas les reproches.', 'Docker, CI/CD, deployments and incidents. We share post-mortems, not blame.', (select id from public.interests where slug = 'devops'), null, now() - interval '64 days'),
