-- messages and final fix-ups
begin;
insert into public.messages (id, circle_id, author_id, body, created_at) values
  ('24416359-493d-5c35-b35a-880f7523d292'::uuid, '6d37f68e-c6c7-594a-bc8e-68731d2cc653'::uuid, '36c44435-65df-51e2-9312-3ba3d6757261'::uuid, 'Bonjour ! Petite question bête : vous mettez vos appels API dans useEffect ou vous passez direct par une lib ?', now() - interval '1310 minutes'),
  ('db11091e-676d-5762-b9e1-b655352b8626'::uuid, '6d37f68e-c6c7-594a-bc8e-68731d2cc653'::uuid, '1dce1d27-78fb-5179-a912-bd23c57d4895'::uuid, 'Pas bête du tout. Pour apprendre, useEffect + fetch c''est bien pour comprendre le cycle. Sur un vrai projet, TanStack Query t''évite de réécrire le cache, les états de chargement et les annulations.', now() - interval '1298 minutes'),
  ('ed236897-a3a8-5ac2-b444-2eeaeb475db5'::uuid, '6d37f68e-c6c7-594a-bc8e-68731d2cc653'::uuid, 'c5284648-64cb-5e9e-a325-1b7a4dd8f2d7'::uuid, '+1. Et pense à annuler la requête dans le cleanup, sinon tu auras des surprises avec StrictMode.', now() - interval '1290 minutes'),
  ('77c5e4ca-e08a-5976-a73c-726ced94a7e2'::uuid, '6d37f68e-c6c7-594a-bc8e-68731d2cc653'::uuid, '36c44435-65df-51e2-9312-3ba3d6757261'::uuid, 'Justement j''ai posté un problème là-dessus, mon effet part deux fois 😅', now() - interval '1281 minutes'),
  ('2f45d9b3-dbf2-505a-9e62-0dd8e8668e8b'::uuid, '6d37f68e-c6c7-594a-bc8e-68731d2cc653'::uuid, 'b8fa65cc-65e1-50ae-aaa8-81cf1e728821'::uuid, 'Quelqu''un a déjà migré un gros Context vers Zustand ? Je cherche des retours avant de me lancer sur Pollen.', now() - interval '420 minutes'),
  ('38d8cc52-06a5-54fd-8e3c-c42a998ec518'::uuid, '6d37f68e-c6c7-594a-bc8e-68731d2cc653'::uuid, '127106c4-6185-57e9-bbd6-4c41c8175c6e'::uuid, 'Oui, sur un dashboard. Le gain vient surtout des sélecteurs : seuls les composants qui lisent la valeur modifiée se re-rendent.', now() - interval '402 minutes'),
  ('c8d87bde-1806-584a-9b94-421e34cf609d'::uuid, '6d37f68e-c6c7-594a-bc8e-68731d2cc653'::uuid, '1dce1d27-78fb-5179-a912-bd23c57d4895'::uuid, 'Avant de migrer, regarde si découper ton contexte en deux (état / actions) ne suffit pas. C''est souvent 80 % du gain.', now() - interval '388 minutes'),
  ('7a62c0be-e818-5027-a6a0-aea5283a1d0d'::uuid, '6d37f68e-c6c7-594a-bc8e-68731d2cc653'::uuid, '60409083-840c-5088-b8b7-9d004e795d26'::uuid, 'Je viens de découvrir le React Compiler sur un petit projet, j''ai pu supprimer pas mal de useMemo. Vous l''avez activé en prod ?', now() - interval '64 minutes'),
  ('b08ed40e-4abf-51b4-9d49-5cdf73ab713e'::uuid, '6d37f68e-c6c7-594a-bc8e-68731d2cc653'::uuid, 'c5284648-64cb-5e9e-a325-1b7a4dd8f2d7'::uuid, 'Sur un projet oui, sans souci pour l''instant. Garde quand même le lint des règles des hooks, le compilateur saute les composants qui ne les respectent pas.', now() - interval '41 minutes'),
  ('6ddb4a69-812e-524a-80b8-7d44d819d64e'::uuid, '66f8e009-78f7-5e84-84c8-46f7f2522bbe'::uuid, '88d23a8a-1440-5cf2-bdb1-fe5096088032'::uuid, 'Bonjour tout le monde. Vous utilisez quoi pour gérer vos environnements ? Je me perds entre venv, pipenv, poetry…', now() - interval '1205 minutes'),
  ('55847ee2-cc66-53c3-b070-72ff809c5bce'::uuid, '66f8e009-78f7-5e84-84c8-46f7f2522bbe'::uuid, 'c783bb00-c6b1-58ac-b011-7167213746d5'::uuid, 'Pour débuter : python -m venv .venv, ça suffit largement. Depuis un an je suis passé à uv, c''est très rapide, mais venv te fait comprendre ce qui se passe.', now() - interval '1190 minutes'),
  ('d5c32054-e2ec-5d17-897a-26ee9e990c9d'::uuid, '66f8e009-78f7-5e84-84c8-46f7f2522bbe'::uuid, '63ce7c64-4bf6-55b1-8c81-39efa16132c2'::uuid, 'J''ai perdu une heure hier parce que pip installait dans un autre Python que celui de VS Code…', now() - interval '1174 minutes'),
  ('aa539f81-e27a-5fc5-8eb6-35196e227655'::uuid, '66f8e009-78f7-5e84-84c8-46f7f2522bbe'::uuid, 'c783bb00-c6b1-58ac-b011-7167213746d5'::uuid, 'Classique. Prends l''habitude de lancer python -m pip install, comme ça tu es sûr que c''est le bon interpréteur.', now() - interval '1168 minutes'),
  ('c7bf4933-0818-5c91-9e60-73105825401a'::uuid, '66f8e009-78f7-5e84-84c8-46f7f2522bbe'::uuid, 'a5019547-4c5d-53d0-9581-5355518d3a38'::uuid, 'Question pour les pythonistes : vous typez vos projets (mypy/pyright) ou pas ?', now() - interval '515 minutes'),
  ('8ccdec60-e8fd-5f89-9405-98b79c17dbb4'::uuid, '66f8e009-78f7-5e84-84c8-46f7f2522bbe'::uuid, 'c783bb00-c6b1-58ac-b011-7167213746d5'::uuid, 'Dès que le projet dépasse quelques fichiers, oui. Pyright en mode basic pour commencer, et on serre la vis petit à petit.', now() - interval '498 minutes'),
  ('0526a260-c93e-5578-9cc5-6b5857781d04'::uuid, '66f8e009-78f7-5e84-84c8-46f7f2522bbe'::uuid, '60409083-840c-5088-b8b7-9d004e795d26'::uuid, 'Je découvre les f-strings avec le = pour déboguer : print(f"{total=}"). Pourquoi personne ne m''en a parlé avant ?', now() - interval '96 minutes'),
  ('c87c7e51-8021-51ea-8ac7-8f8cdd74b20e'::uuid, '66f8e009-78f7-5e84-84c8-46f7f2522bbe'::uuid, '88d23a8a-1440-5cf2-bdb1-fe5096088032'::uuid, 'Ah mais c''est génial ça, merci !', now() - interval '77 minutes'),
  ('4ae474de-8e4e-5b81-93e9-2381e04e6017'::uuid, '496ee400-d798-5c41-97d9-06f86016e094'::uuid, 'b8fa65cc-65e1-50ae-aaa8-81cf1e728821'::uuid, 'Je teste un RAG sur la doc de Pollen. Les réponses en anglais sont bonnes, en français c''est la loterie. J''ai ouvert un problème.', now() - interval '1120 minutes'),
  ('7d515ab7-47d6-530d-b10e-eb37b9a40c19'::uuid, '496ee400-d798-5c41-97d9-06f86016e094'::uuid, 'c783bb00-c6b1-58ac-b011-7167213746d5'::uuid, 'Tu utilises quel modèle d''embeddings ? Beaucoup sont entraînés surtout sur de l''anglais.', now() - interval '1102 minutes'),
  ('b1396117-224a-54db-9a91-116cfcc6993a'::uuid, '496ee400-d798-5c41-97d9-06f86016e094'::uuid, 'b8fa65cc-65e1-50ae-aaa8-81cf1e728821'::uuid, 'all-MiniLM-L6-v2, le classique…', now() - interval '1095 minutes'),
  ('1a9883d3-acde-5e1f-bf1c-62e3f4451fc8'::uuid, '496ee400-d798-5c41-97d9-06f86016e094'::uuid, 'c783bb00-c6b1-58ac-b011-7167213746d5'::uuid, 'Voilà une piste : il est essentiellement anglophone. Essaie un modèle multilingue avant de toucher au reste du pipeline.', now() - interval '1088 minutes'),
  ('a7bc9e47-58cf-5678-8ea6-942177e6bc3e'::uuid, '496ee400-d798-5c41-97d9-06f86016e094'::uuid, '88d23a8a-1440-5cf2-bdb1-fe5096088032'::uuid, 'Vous avez un jeu de données sympa pour s''entraîner à nettoyer avec pandas ? Les miens sont trop propres.', now() - interval '340 minutes'),
  ('c32a436c-f2ff-593a-9c02-83e6eb815d5e'::uuid, '496ee400-d798-5c41-97d9-06f86016e094'::uuid, '63ce7c64-4bf6-55b1-8c81-39efa16132c2'::uuid, 'Les données ouvertes de data.gouv.fr, il y a de quoi faire niveau colonnes mal nommées et dates dans tous les formats 😄', now() - interval '322 minutes'),
  ('708f7d0f-bfe7-5148-9ea3-82a2c7f5c9c0'::uuid, '496ee400-d798-5c41-97d9-06f86016e094'::uuid, 'c783bb00-c6b1-58ac-b011-7167213746d5'::uuid, 'Et n''oublie pas de séparer train et test AVANT tout nettoyage qui apprend quelque chose des données (moyennes, scalers…).', now() - interval '310 minutes'),
  ('cb13fa84-58fa-5fed-86ee-08dc14d0d292'::uuid, '496ee400-d798-5c41-97d9-06f86016e094'::uuid, '127106c4-6185-57e9-bbd6-4c41c8175c6e'::uuid, 'Je lis vos échanges pour apprendre, continuez comme ça 🙏', now() - interval '58 minutes'),
  ('1d06cd99-2847-5a8b-91cb-063bd39a4dbb'::uuid, 'e1e088aa-9ad2-5c3f-995f-4c756113766e'::uuid, '92eb883f-d370-5c4f-ba14-20929fde18f2'::uuid, 'Hello! Anyone else fighting with push notifications on Android 14? Works on Pixel, not on half of my users'' phones.', now() - interval '1250 minutes'),
  ('18cd42a2-2f78-54a8-9d56-b73427ed4524'::uuid, 'e1e088aa-9ad2-5c3f-995f-4c756113766e'::uuid, 'c783bb00-c6b1-58ac-b011-7167213746d5'::uuid, 'Pas encore, mais mes utilisateurs ont surtout des Tecno et des Infinix, donc ça m''intéresse. Je suis ton post.', now() - interval '1231 minutes'),
  ('ffbfc607-0b9b-5610-8a53-1bf8f551fa30'::uuid, 'e1e088aa-9ad2-5c3f-995f-4c756113766e'::uuid, 'b8fa65cc-65e1-50ae-aaa8-81cf1e728821'::uuid, 'Vous conseillez quoi pour une première app : Flutter ou React Native, quand on vient de React ?', now() - interval '760 minutes'),
  ('a8892e74-229f-58c8-9001-c2c6b664ce71'::uuid, 'e1e088aa-9ad2-5c3f-995f-4c756113766e'::uuid, '92eb883f-d370-5c4f-ba14-20929fde18f2'::uuid, 'Si tu viens de React, React Native avec Expo : tu réutilises tes réflexes. Flutter est top aussi, mais tu apprends Dart et un nouveau modèle de widgets en plus.', now() - interval '742 minutes'),
  ('d10b6811-320b-599b-90a2-d8269b526afb'::uuid, 'e1e088aa-9ad2-5c3f-995f-4c756113766e'::uuid, '127106c4-6185-57e9-bbd6-4c41c8175c6e'::uuid, 'Expo m''a bien simplifié la vie pour les builds, je confirme.', now() - interval '730 minutes'),
  ('d6cf5022-6f2f-5367-9a60-afb79d0796ee'::uuid, 'e1e088aa-9ad2-5c3f-995f-4c756113766e'::uuid, 'c783bb00-c6b1-58ac-b011-7167213746d5'::uuid, 'Petit rappel du jour : tester sur un vrai téléphone d''entrée de gamme. Mon écran d''accueil mettait 6 secondes sur un appareil à 2 Go de RAM.', now() - interval '118 minutes'),
  ('2f557c42-e341-5674-b3b6-de3d6e57e156'::uuid, 'e1e088aa-9ad2-5c3f-995f-4c756113766e'::uuid, '92eb883f-d370-5c4f-ba14-20929fde18f2'::uuid, 'Toujours. Et en 3G dégradée aussi, on découvre des choses.', now() - interval '102 minutes'),
  ('6144897d-67d5-53a1-963e-054427415ff6'::uuid, '9c3a733f-4385-5337-8c12-487fed0fed37'::uuid, '4130c542-5ee6-51eb-a0da-80bd3cb67520'::uuid, 'Petit sondage : vous déployez comment vos side-projects ? Je vois passer pas mal de VPS avec Docker Compose ces temps-ci.', now() - interval '1380 minutes'),
  ('c470d6ba-41fe-5c0e-a04f-9084140bc262'::uuid, '9c3a733f-4385-5337-8c12-487fed0fed37'::uuid, 'a5019547-4c5d-53d0-9581-5355518d3a38'::uuid, 'VPS + Compose + Caddy devant. Simple, pas cher, et je comprends tout ce qui tourne.', now() - interval '1362 minutes'),
  ('b477f725-de1b-5727-92c7-f70d57d94668'::uuid, '9c3a733f-4385-5337-8c12-487fed0fed37'::uuid, 'b8fa65cc-65e1-50ae-aaa8-81cf1e728821'::uuid, 'Pareil, mais derrière Nginx, et j''ai des 502 aléatoires sous charge. J''ai posté les logs si quelqu''un a une idée.', now() - interval '1340 minutes'),
  ('d0c968fe-f434-5942-8f5d-3b1fc0d5f5a4'::uuid, '9c3a733f-4385-5337-8c12-487fed0fed37'::uuid, '36c44435-65df-51e2-9312-3ba3d6757261'::uuid, 'Mon image Docker faisait 1,4 Go… Grâce à la réponse de Mathieu elle est descendue à 180 Mo. Merci !', now() - interval '610 minutes'),
  ('7e1f54de-9a66-546f-8e4e-210965e5cd15'::uuid, '9c3a733f-4385-5337-8c12-487fed0fed37'::uuid, '4130c542-5ee6-51eb-a0da-80bd3cb67520'::uuid, 'Ça fait plaisir ! Le multi-stage, c''est le genre de truc qu''on n''oublie plus après.', now() - interval '596 minutes'),
  ('83916e1c-f8e9-5a9b-a631-d7e55e0e7433'::uuid, '9c3a733f-4385-5337-8c12-487fed0fed37'::uuid, '127106c4-6185-57e9-bbd6-4c41c8175c6e'::uuid, 'Vous mettez des healthchecks dans vos fichiers Compose ? Je me demande si ça vaut le coup sur un petit projet.', now() - interval '205 minutes'),
  ('b96204ff-cd20-5aeb-9bdc-52a0ad5b4d8c'::uuid, '9c3a733f-4385-5337-8c12-487fed0fed37'::uuid, 'a5019547-4c5d-53d0-9581-5355518d3a38'::uuid, 'Oui, surtout avec depends_on et condition: service_healthy. Ça évite que l''API démarre avant que Postgres soit prêt.', now() - interval '190 minutes'),
  ('ee313483-cabe-5bff-be3d-2e0c8c305735'::uuid, '9c3a733f-4385-5337-8c12-487fed0fed37'::uuid, '92eb883f-d370-5c4f-ba14-20929fde18f2'::uuid, 'Je note pour ma CI, merci.', now() - interval '35 minutes'),
  ('687a7ecb-dbc3-53cf-9485-500e4d058bcd'::uuid, '51fa73c3-fd0b-5c20-b5bd-708aa560249e'::uuid, '36c44435-65df-51e2-9312-3ba3d6757261'::uuid, 'Je passe mon premier entretien technique la semaine prochaine. Des conseils pour ne pas paniquer en live coding ?', now() - interval '1420 minutes'),
  ('487279b1-0d6e-5b56-91bb-7522ae0de46d'::uuid, '51fa73c3-fd0b-5c20-b5bd-708aa560249e'::uuid, 'c5284648-64cb-5e9e-a325-1b7a4dd8f2d7'::uuid, 'Pense à voix haute. On évalue ton raisonnement bien plus que le résultat final. Et tu as le droit de dire « je ne sais pas, voici comment je chercherais ».', now() - interval '1401 minutes'),
  ('ef1a83ff-84ae-5573-b522-7f8f60e210b3'::uuid, '51fa73c3-fd0b-5c20-b5bd-708aa560249e'::uuid, '4130c542-5ee6-51eb-a0da-80bd3cb67520'::uuid, 'Et pose des questions sur l''énoncé avant de coder. C''est un bon signal, pas un aveu de faiblesse.', now() - interval '1388 minutes'),
  ('b7ba6f14-46e7-5ca2-b3f1-729bc519ed24'::uuid, '51fa73c3-fd0b-5c20-b5bd-708aa560249e'::uuid, '36c44435-65df-51e2-9312-3ba3d6757261'::uuid, 'Merci à vous deux, ça me rassure.', now() - interval '1375 minutes'),
  ('48e918bc-683d-5645-9ded-ab31124679b7'::uuid, '51fa73c3-fd0b-5c20-b5bd-708aa560249e'::uuid, '63ce7c64-4bf6-55b1-8c81-39efa16132c2'::uuid, 'Vous négociez votre salaire en sortie d''alternance, ou vous prenez ce qu''on vous propose ?', now() - interval '480 minutes'),
  ('e59f35f5-3325-566e-b7f3-2606888ab542'::uuid, '51fa73c3-fd0b-5c20-b5bd-708aa560249e'::uuid, 'a5019547-4c5d-53d0-9581-5355518d3a38'::uuid, 'Toujours discuter, poliment et avec des éléments concrets : ce que tu as livré, ce que tu sais faire en autonomie. Le pire qu''on puisse te répondre, c''est non.', now() - interval '462 minutes'),
  ('bba8a1ef-4eb4-5d26-b3e0-4095f958514f'::uuid, '51fa73c3-fd0b-5c20-b5bd-708aa560249e'::uuid, '1dce1d27-78fb-5179-a912-bd23c57d4895'::uuid, 'Et renseigne-toi sur les grilles de ta région avant, ça évite de viser trop bas.', now() - interval '451 minutes'),
  ('152fbd1c-9e56-5128-a394-8ab11bc3b841'::uuid, '51fa73c3-fd0b-5c20-b5bd-708aa560249e'::uuid, '88d23a8a-1440-5cf2-bdb1-fe5096088032'::uuid, 'Petite victoire : mon premier merge request a été accepté aujourd''hui, après trois allers-retours de revue 🎉', now() - interval '88 minutes'),
  ('70562197-d734-5f81-b11e-841229a0b798'::uuid, '51fa73c3-fd0b-5c20-b5bd-708aa560249e'::uuid, '1dce1d27-78fb-5179-a912-bd23c57d4895'::uuid, 'Bravo ! Trois allers-retours, c''est parfaitement normal, même après dix ans.', now() - interval '70 minutes')
on conflict (id) do update set circle_id = excluded.circle_id, author_id = excluded.author_id,
  body = excluded.body, created_at = excluded.created_at;

-- reputation is the seed's (the accept trigger may have moved it while upserting)
update public.profiles p set reputation = v.reputation
from (values
  ('127106c4-6185-57e9-bbd6-4c41c8175c6e'::uuid, 164),
  ('c5284648-64cb-5e9e-a325-1b7a4dd8f2d7'::uuid, 482),
