  ('c783bb00-c6b1-58ac-b011-7167213746d5'::uuid, 187),
  ('60409083-840c-5088-b8b7-9d004e795d26'::uuid, 121),
  ('36c44435-65df-51e2-9312-3ba3d6757261'::uuid, 18),
